B.avk=new A.a(B.c,["Stoarce pulpa","Preseaz\u0103 castrave\u021bii \xeen sit\u0103 sau \xeen m\xe2ini curate, elimin\xe2nd lichidul acumulat.","Pulpa este umed\u0103, dar nu picur\u0103 abundent.","",1,B.b],t.M)
B.anq=new A.a(B.c,["Amestec\u0103 sosul","Combin\u0103 iaurtul, castrave\u021bii, m\u0103rarul, usturoiul \u0219i uleiul m\u0103surat. Adaug\u0103 sucul de l\u0103m\xe2ie treptat, dup\u0103 gust.","Sosul este gros \u0219i omogen.","",3,B.b],t.M)
