B.are=new A.a(B.c,["Combin\u0103 ingredientele","Pune peste frunze m\u0103rul, meri\u0219oarele, nucile tocate \u0219i miezul semin\u021belor de floarea-soarelui.","Ingredientele sunt distribuite \xeen bol.","",2,B.b],t.M)
B.arJ=new A.a(B.c,["Adaug\u0103 vinegreta","Toarn\u0103 vinegreta m\u0103surat\u0103 \u0219i \xeentoarce salata delicat, ridic\xe2nd frunzele de jos.","Frunzele au un strat sub\u021bire de sos.","",4,B.b],t.M)
