B.ajQ=new A.a(B.i,["Condimenteaz\u0103 carnea","Amestec\u0103 vita \u0219i porcul cu bicarbonatul \u0219i condimentele.","",-1,B.b,""],t.M)
B.ajI=new A.a(B.i,["\xcencorporeaz\u0103 supa treptat","\xcencorporeaz\u0103 supa \xeen tran\u0219e \u0219i omogenizeaz\u0103 circa 10 minute, p\u0103str\xe2nd pasta rece.","",-1,B.x,""],t.M)
