B.aiX=new A.a(B.i,["G\u0103te\u0219te pe toate fe\u021bele","G\u0103te\u0219te pe toate fe\u021bele, f\u0103r\u0103 flac\u0103r\u0103 direct\u0103; \xeencepe verificarea dup\u0103 10 minute.","",-1,B.x,""],t.M)
