B.ait=new A.a(B.i,["Coace \u0219i urm\u0103re\u0219te grosimea","Coace \u0219i \xeencepe verificarea dup\u0103 20 de minute; continu\u0103 dup\u0103 grosime.","",-1,B.O,""],t.M)
