B.agr=new A.a(B.i,["Calculeaz\u0103 timpul din ambalaj","Fierbe cu 1 minut mai pu\u021bin dec\xe2t ambalajul; exemplu 8 minute dac\u0103 pachetul cere 9.","",-1,B.b,""],t.M)
