B.ag3=new A.a(B.i,["\xcenc\u0103lze\u0219te cuptorul \u0219i preg\u0103te\u0219te tava","Pre\xeenc\u0103lze\u0219te la 200\xb0C static / 190\xb0C ventilat; preg\u0103te\u0219te tava \u0219i capacul.","",-1,B.b,""],t.M)
B.agL=new A.a(B.i,["Tamponeaz\u0103 pulpele","Tamponeaz\u0103 puiul f\u0103r\u0103 sp\u0103lare; igienizeaz\u0103 m\xe2inile \u0219i suprafe\u021bele.","",0,B.b,""],t.M)
B.ajw=new A.a(B.i,["Prepar\u0103 amestecul de usturoi","Amestec\u0103 uleiul cu usturoiul \u0219i condimentele; unge pulpele.","",1,B.b,""],t.M)
B.aj7=new A.a(B.i,["A\u0219az\u0103 \u0219i acoper\u0103","A\u0219az\u0103 cu pielea \xeen sus, adaug\u0103 50 ml ap\u0103 pe margine \u0219i acoper\u0103.","",2,B.b,""],t.M)
B.aiL=new A.a(B.i,["Coace acoperit","Coace acoperit 30 de minute; descoper\u0103 cu grij\u0103.","",2,B.aq,""],t.M)
