B.aip=new A.a(B.i,["Verific\u0103 interiorul \u0219i serve\u0219te","Confirm\u0103 minimum 74\xb0C \xeen toate buc\u0103\u021bile, f\u0103r\u0103 contact cu osul; las\u0103 5 minute \u0219i serve\u0219te.","",5,B.v,""],t.M)
