B.afh=new A.a(B.i,["Toac\u0103 \u0219i \xeenmoaie ceapa","\xcenmoaie ceapa \xeen ulei aproximativ 8 minute, f\u0103r\u0103 rumenire.","",0,B.a_,""],t.M)
B.ajD=new A.a(B.i,["Adaug\u0103 orezul \u0219i r\u0103core\u0219te baza","Amestec\u0103 orezul \u0219i pasta cu ceapa 2 minute; r\u0103core\u0219te \xeenainte de carne.","",0,B.S,""],t.M)
B.agR=new A.a(B.i,["Amestec\u0103 umplutura","Omogenizeaz\u0103 carnea cu baza rece, 100 ml ap\u0103 \u0219i condimente; sare prudent.","",1,B.b,""],t.M)
B.ahN=new A.a(B.i,["Ruleaz\u0103 f\u0103r\u0103 s\u0103 \xeende\u0219i","Umple cu circa o lingur\u0103 \u0219i ruleaz\u0103 lejer, \xeenchiz\xe2nd laturile.","",2,B.b,""],t.M)
B.agO=new A.a(B.i,["Aranjeaz\u0103 oala \xeen straturi","Pune varz\u0103 \u0219i afum\u0103tur\u0103 la baz\u0103; a\u0219az\u0103 rulourile, aromele \u0219i varza r\u0103mas\u0103.","",3,B.b,""],t.M)
