B.ahr=new A.a(B.i,["Fierbe lent \u0219i urm\u0103re\u0219te lichidul","Fierbe lent 180 de minute; verific\u0103 lichidul periodic \u0219i completeaz\u0103 fierbinte.","",4,B.ey,""],t.M)
B.agG=new A.a(B.i,["Testeaz\u0103 o sarma \u0219i termin\u0103","Verific\u0103 minimum 71\xb0C \xeen umplutur\u0103, orez moale \u0219i varz\u0103 fraged\u0103; dac\u0103 trebuie, continu\u0103 20 de minute.","",5,B.O,""],t.M)
