B.afn=new A.a(B.i,["P\u0103streaz\u0103 supa \u0219i por\u021bioneaz\u0103 carnea","Strecoar\u0103 \u0219i p\u0103streaz\u0103 500 ml sup\u0103 cald\u0103; por\u021bioneaz\u0103 puiul g\u0103tit.","",0,B.b,""],t.M)
