B.ag_=new A.a(B.i,["P\u0103streaz\u0103 zeama \u0219i taie carnea","P\u0103streaz\u0103 200 ml zeam\u0103 numai dac\u0103 nu este prea s\u0103rat\u0103; taie carnea la 3 cm.","",0,B.b,""],t.M)
B.afl=new A.a(B.i,["Toac\u0103 varza \u0219i ceapa","Taie varza fidelu\u021b\u0103, fr\u0103m\xe2nt\u0103 u\u0219or cu foarte pu\u021bin\u0103 sare \u0219i toac\u0103 ceapa.","",1,B.b,""],t.M)
B.ahO=new A.a(B.i,["\xcenmoaie ceapa","\xcenmoaie ceapa \xeen ulei 7 minute; \xeenc\u0103lze\u0219te cuptorul la 180\xb0C static / 170\xb0C ventilat.","",2,B.aa,""],t.M)
B.aiW=new A.a(B.i,["Mic\u0219oreaz\u0103 volumul verzei","\xcen\u0103bu\u0219\u0103 varza 10 minute \xeen tran\u0219e; adaug\u0103 ro\u0219iile, aromele, carnea \u0219i lichidul.","",2,B.x,""],t.M)
B.ajL=new A.a(B.i,["G\u0103te\u0219te acoperit la cuptor","Coace acoperit 45 de minute; prelunge\u0219te p\xe2n\u0103 varza este fraged\u0103.","",3,B.av,""],t.M)
