B.ahl=new A.a(B.i,["Adaug\u0103 maz\u0103rea potrivit tipului","Congelat\u0103: fierbe 10 minute/conform ambalajului. La conserv\u0103: ro\u0219iile fierb 10 minute, apoi boabele doar 3\u20135 minute.","",2,B.x,""],t.M)
B.ajS=new A.a(B.i,["Leag\u0103 sosul","Adaug\u0103 ro\u0219iile dac\u0103 nu sunt deja \xeen vas; \xeencorporeaz\u0103 f\u0103ina desf\u0103cut\u0103 \xeen ap\u0103 \u0219i fierbe 8 minute.","",3,B.a_,""],t.M)
