B.aga=new A.a(B.i,["Porne\u0219te fierberea lent\u0103","Completeaz\u0103 cu restul apei p\xe2n\u0103 aproape de nivelul c\u0103rnii \u0219i porne\u0219te fierberea domoal\u0103.","",2,B.b,""],t.M)
