B.afM=new A.a(B.i,["\xcenmoaie ceapa \u0219i morcovul","\xcenmoaie ceapa \u0219i morcovul circa 7 minute.","",-1,B.aa,""],t.M)
B.agw=new A.a(B.i,["G\u0103te\u0219te ciupercile","Adaug\u0103 ciupercile \u0219i g\u0103te\u0219te circa 8 minute, p\xe2n\u0103 scade lichidul.","",-1,B.a_,""],t.M)
B.aj2=new A.a(B.i,["Hidrateaz\u0103 par\u021bial orezul","Amestec\u0103 orezul 1 minut, adaug\u0103 100 ml ap\u0103 \u0219i g\u0103te\u0219te circa 5 minute; asezoneaz\u0103 \u0219i r\u0103core\u0219te.","",-1,B.v,""],t.M)
