B.ajb=new A.a(B.i,["Fierbe p\xe2n\u0103 se p\u0103trunde orezul","Fierbe domol acoperit; verific\u0103 dup\u0103 45 de minute \u0219i continu\u0103 p\xe2n\u0103 orezul este complet moale.","",-1,B.av,""],t.M)
