B.aiF=new A.a(B.i,["Asezoneaz\u0103","Unge feliile cu amestecul de ulei, usturoi \u0219i condimente.","",-1,B.b,""],t.M)
B.ag9=new A.a(B.i,["Pune lichidul \u0219i acoper\u0103","A\u0219az\u0103 \xeentr-un strat; adaug\u0103 vinul \u0219i 100 ml ap\u0103, apoi acoper\u0103.","",-1,B.b,""],t.M)
