B.awD=new A.a(B.bD,["\u2022 600 g p\u0103st\u0103i proaspete sau congelate de fasole verde\n\u2022 1 ceap\u0103 mare\n\u2022 3 c\u0103\u021bei usturoi\n\u2022 250 g ro\u0219ii pasate\n\u2022 2 linguri ulei (30 ml)\n\u2022 150 ml ap\u0103 fierbinte la \xeenceput; rezerv\u0103\n\u2022 M\u0103rar, sare \u0219i piper dup\u0103 gust","Folose\u0219te p\u0103st\u0103i proaspete fragede sau congelate. Varianta la conserv\u0103 este deja g\u0103tit\u0103 \u0219i necesit\u0103 doar \xeenc\u0103lzire \xeen sos, deci nu urmeaz\u0103 fierberea lung\u0103 de aici. Timpii afi\u0219a\u021bi sunt estim\u0103ri pentru cantitatea original\u0103; urm\u0103re\u0219te verific\u0103rile din pa\u0219i \u0219i prelunge\u0219te g\u0103tirea c\xe2nd este nevoie.","Crati\u021b\u0103 cu capac, lingur\u0103, toc\u0103tor \u0219i cu\u021bit.","\xcenmoaie p\u0103st\u0103ile \xeenainte de ro\u0219ii. O p\u0103staie matur\u0103 \u0219i fibroas\u0103 nu va deveni pl\u0103cut\u0103 doar prin sos mai mult.","",null,"",!0,!0,B.UE,u.Y,"28.10.2026",15,40,55,u.a,"",!0],t.t4)
B.a8O=new A.a(B.h,["Cur\u0103\u021b\u0103 \u0219i taie p\u0103st\u0103ile","La cele proaspete \xeendep\u0103rteaz\u0103 capetele \u0219i eventualele a\u021be de pe margini. Spal\u0103 \u0219i taie buc\u0103\u021bi de 4\u20135 cm. Elimin\u0103 p\u0103st\u0103ile foarte fibroase. Cele congelate se folosesc direct, conform ambalajului.","P\u0103st\u0103ile nu au capete tari sau a\u021be vizibile.","Dac\u0103 o p\u0103staie se \xeendoaie ca o sfoar\u0103 \u0219i are coaja foarte tare, este prea matur\u0103 pentru o textur\u0103 fin\u0103.",-1,B.b,""],t.M)
B.a8H=new A.a(B.h,["Preg\u0103te\u0219te aromele","Toac\u0103 ceapa \xeen cubule\u021be mici. Cur\u0103\u021b\u0103 usturoiul \u0219i zdrobe\u0219te-l, dar \u021bine-l separat. Spal\u0103 \u0219i toac\u0103 m\u0103rarul, elimin\xe2nd tulpinile groase.","Aromele sunt gata \xeenainte s\u0103 porne\u0219ti focul.","Usturoiul intr\u0103 spre final; dac\u0103 \xeel pui acum cu ceapa, se poate arde.",-1,B.b,""],t.M)
B.a8P=new A.a(B.h,["\xcenmoaie ceapa","Pune uleiul \u0219i ceapa \xeen crati\u021b\u0103, la foc mediu-mic. Adaug\u0103 un praf de sare \u0219i amestec\u0103 7 minute, p\xe2n\u0103 ceapa devine moale.","Ceapa este translucid\u0103, f\u0103r\u0103 margini negre.","Dac\u0103 se prinde, adaug\u0103 o lingur\u0103 de ap\u0103 \u0219i redu focul.",-1,B.aa,""],t.M)
B.a8F=new A.a(B.h,["Fierbe p\u0103st\u0103ile acoperit","Adaug\u0103 p\u0103st\u0103ile \u0219i 150 ml ap\u0103 fierbinte. Amestec\u0103, acoper\u0103 \u0219i fierbe domol. \xcencepe verificarea dup\u0103 15 minute, dar respect\u0103 timpul de pe ambalaj dac\u0103 folose\u0219ti congelate. Completeaz\u0103 pu\u021bin\u0103 ap\u0103 dac\u0103 se usuc\u0103.","P\u0103st\u0103ile sunt g\u0103tite \u0219i aproape la fr\u0103gezimea dorit\u0103.","Nu gusta p\u0103st\u0103i crude sau doar \xeenc\u0103lzite; g\u0103te\u0219te complet \xeenainte de degustare.",-1,B.u,""],t.M)
B.a7Y=new A.a(B.h,["Adaug\u0103 ro\u0219iile","Pune ro\u0219iile pasate \u0219i amestec\u0103. Fierbe f\u0103r\u0103 capac aproximativ 10 minute, la foc mic-mediu, p\xe2n\u0103 sosul scade. \xcentoarce p\u0103st\u0103ile u\u0219or, f\u0103r\u0103 s\u0103 le zdrobe\u0219ti.","P\u0103st\u0103ile sunt fragede, iar sosul nu mai este apos.","Dac\u0103 p\u0103st\u0103ile sunt \xeenc\u0103 tari, pune capacul \u0219i continu\u0103 cu pu\u021bin\u0103 ap\u0103; reducerea vine dup\u0103 fr\u0103gezire.",-1,B.x,""],t.M)
B.abk=new A.a(B.h,["Pune usturoiul","Adaug\u0103 usturoiul zdrobit \u0219i amestec\u0103 1 minut la foc mic. Opre\u0219te apoi focul.","Usturoiul este distribuit \xeen sos \u0219i nu s-a ars.","Pentru gust mai discret, pune \xeent\xe2i o parte \u0219i completeaz\u0103 dup\u0103 degustare.",-1,B.ab,""],t.M)
B.a7z=new A.a(B.h,["Ajusteaz\u0103 sosul","Dac\u0103 este prea gros, pune c\xe2te o lingur\u0103 de ap\u0103 fierbinte \u0219i amestec\u0103. Dac\u0103 este prea sub\u021bire, scoate p\u0103st\u0103ile \u0219i redu lichidul separat, apoi reune\u0219te. Gust\u0103 \u0219i potrive\u0219te sarea \u0219i piperul.","Sosul \xeembrac\u0103 p\u0103st\u0103ile \u0219i nu se separ\u0103 \xeen ap\u0103 \u0219i past\u0103.","Nu \xeengro\u0219a cu f\u0103in\u0103: aceast\u0103 variant\u0103 se leag\u0103 prin reducere.",-1,B.b,""],t.M)
B.a93=new A.a(B.h,["Presar\u0103 m\u0103rar \u0219i serve\u0219te","Pune m\u0103rarul tocat dup\u0103 oprirea focului. Amestec\u0103 u\u0219or \u0219i serve\u0219te ca m\xe2ncare de sine st\u0103t\u0103toare sau garnitur\u0103.","P\u0103st\u0103ile sunt fragede, dar \xee\u0219i p\u0103streaz\u0103 forma.","La re\xeenc\u0103lzire adaug\u0103 o lingur\u0103 de ap\u0103 dac\u0103 sosul s-a \xeengro\u0219at.",-1,B.b,""],t.M)
B.XL=s([B.a8O,B.a8H,B.a8P,B.a8F,B.a7Y,B.abk,B.a7z,B.a93],t.J)
B.ahn=new A.a(B.i,["Cur\u0103\u021b\u0103 \u0219i taie p\u0103st\u0103ile","Cur\u0103\u021b\u0103 \u0219i taie p\u0103st\u0103ile proaspete; pe cele congelate folose\u0219te-le conform ambalajului.","",-1,B.b,""],t.M)
B.agt=new A.a(B.i,["Preg\u0103te\u0219te aromele","Toac\u0103 ceapa, zdrobe\u0219te usturoiul \u0219i preg\u0103te\u0219te m\u0103rarul separat.","",-1,B.b,""],t.M)
B.ajN=new A.a(B.i,["Fierbe p\u0103st\u0103ile acoperit","\xcen\u0103bu\u0219\u0103 p\u0103st\u0103ile cu 150 ml ap\u0103; verific\u0103 dup\u0103 15 minute \u0219i urmeaz\u0103 ambalajul pentru congelate.","",-1,B.u,""],t.M)
B.afw=new A.a(B.i,["Adaug\u0103 ro\u0219iile","Adaug\u0103 ro\u0219iile \u0219i scade descoperit aproximativ 10 minute.","",-1,B.x,""],t.M)
B.afK=new A.a(B.i,["Pune usturoiul","\xcencorporeaz\u0103 usturoiul \u0219i mai g\u0103te\u0219te 1 minut la foc mic.","",-1,B.ab,""],t.M)
B.afm=new A.a(B.i,["Ajusteaz\u0103 sosul","Regleaz\u0103 consisten\u021ba \u0219i asezoneaz\u0103 dup\u0103 gust.","",-1,B.b,""],t.M)
