B.ajs=new A.a(B.i,["P\u0103streaz\u0103 supa \u0219i taie carnea","Por\u021bioneaz\u0103 puiul; p\u0103streaz\u0103 700 ml sup\u0103 cald\u0103 \u0219i p\xe2n\u0103 la 300 ml rezerv\u0103.","",-1,B.b,""],t.M)
