B.agg=new A.a(B.i,["Op\u0103re\u0219te scurt","Op\u0103re\u0219te \xeen tran\u0219e circa 1 minut, p\xe2n\u0103 se las\u0103; scurge \u0219i r\u0103core\u0219te rapid.","",-1,B.ab,""],t.M)
B.ai6=new A.a(B.i,["Scurge \u0219i toac\u0103","Scurge bine \u0219i toac\u0103 spanacul; preg\u0103te\u0219te ceapa \u0219i o parte din usturoi.","",-1,B.b,""],t.M)
B.ai_=new A.a(B.i,["F\u0103 sosul de lapte","Amestec\u0103 f\u0103ina 1 minut; \xeencorporeaz\u0103 treptat 150 ml lapte, cu telul.","",-1,B.ab,""],t.M)
