B.ai8=new A.a(B.i,["Termin\u0103 \xeenmuierea morcovului","Adaug\u0103 100 ml ap\u0103 \u0219i \xeen\u0103bu\u0219\u0103 aproximativ 5 minute, p\xe2n\u0103 morcovul este aproape fraged.","",-1,B.v,""],t.M)
B.agp=new A.a(B.i,["Adaug\u0103 maz\u0103rea","Adaug\u0103 maz\u0103rea \u0219i 50 ml ap\u0103; dup\u0103 reluarea fierberii verific\u0103 la 8 minute ori conform ambalajului.","",-1,B.a_,""],t.M)
