B.aiM=new A.a(B.i,["Porne\u0219te fierberea","Acoper\u0103 cu ap\u0103 rece cu 2\u20133 cm peste cartofi, s\u0103reaz\u0103 \u0219i adu la fierbere domoal\u0103.","",-1,B.b,""],t.M)
B.aiG=new A.a(B.i,["Verific\u0103 p\u0103trunderea","Verific\u0103 dup\u0103 20 de minute; continu\u0103 p\xe2n\u0103 furculi\u021ba traverseaz\u0103 u\u0219or un cub mare.","",-1,B.O,""],t.M)
B.aiN=new A.a(B.i,["\xcenc\u0103lze\u0219te laptele","\xcenc\u0103lze\u0219te 150 ml lapte \u0219i preg\u0103te\u0219te untul cuburi; p\u0103streaz\u0103 rezerva separat.","",-1,B.b,""],t.M)
