B.ahY=new A.a(B.i,["Zdrobe\u0219te c\xe2t sunt fierbin\u021bi","Zdrobe\u0219te fierbinte cu presa sau zdrobitorul manual; f\u0103r\u0103 blender.","",-1,B.b,""],t.M)
B.ags=new A.a(B.i,["\xcencorporeaz\u0103 untul \u0219i laptele","\xcencorporeaz\u0103 untul \xeen tran\u0219e, apoi laptele cald treptat, ajust\xe2nd consisten\u021ba.","",-1,B.b,""],t.M)
