B.axr=new A.a(B.l,["Cur\u0103\u021b\u0103 \u0219i taie legumele",-1,B.b,"","Feliaz\u0103 ciupercile, toac\u0103 ceapa \u0219i usturoiul, taie cartoful cuburi de 1\u20132 cm.",""],t.M)
B.az2=new A.a(B.l,["\xcenmoaie ceapa",0,B.v,"","Tope\u0219te untul \u0219i g\u0103te\u0219te ceapa la foc mic aproximativ 5 minute.",""],t.M)
B.awS=new A.a(B.l,["G\u0103te\u0219te ciupercile",0,B.b,"","Adaug\u0103 ciupercile \u0219i g\u0103te\u0219te p\xe2n\u0103 scade mare parte din apa lor; adaug\u0103 usturoiul spre final.",""],t.M)
B.axg=new A.a(B.l,["Adaug\u0103 cartoful \u0219i lichidul",1,B.b,"","Adaug\u0103 cartoful \u0219i 500 ml lichid fierbinte; adu la fierbere.",""],t.M)
B.axd=new A.a(B.l,["Fierbe p\xe2n\u0103 cartoful este moale",1,B.O,"","Fierbe domol aproximativ 20 de minute \u0219i verific\u0103 un cub de cartof.",""],t.M)
B.axy=new A.a(B.l,["Paseaz\u0103 \xeen siguran\u021b\u0103",2,B.b,"","Ia oala de pe foc \u0219i paseaz\u0103 fin cu blenderul vertical.",""],t.M)
B.aye=new A.a(B.l,["\xcencorporeaz\u0103 sm\xe2nt\xe2na",2,B.b,"","Adaug\u0103 sm\xe2nt\xe2na lichid\u0103, \xeenc\u0103lze\u0219te u\u0219or \u0219i ajusteaz\u0103 consisten\u021ba.",""],t.M)
B.axX=new A.a(B.l,["Serve\u0219te \u0219i p\u0103streaz\u0103 restul",5,B.b,"","Serve\u0219te simpl\u0103; crutoanele sunt o asociere op\u021bional\u0103, separat\u0103 de cantit\u0103\u021bile re\u021betei. Serve\u0219te cald. R\u0103ce\u0219te prompt restul \xeen recipiente mici \u0219i pune la frigider \xeen cel mult 2 ore. Re\xeenc\u0103lze\u0219te por\u021biile la minimum 74\xb0C.",""],t.M)
