B.azj=new A.a(B.l,["Strecoar\u0103 baza",-1,B.b,"","Scoate oasele \u0219i ceapa, apoi strecoar\u0103 fin lichidul \xeen vas curat.",""],t.M)
B.ayQ=new A.a(B.l,["G\u0103te\u0219te burta",1,B.bK,"","Adaug\u0103 burta t\u0103iat\u0103 f\xe2\u0219ii \u0219i gogo\u0219arul; fierbe dup\u0103 etichet\u0103, verific\xe2nd orientativ dup\u0103 40 de minute.",""],t.M)
B.axU=new A.a(B.l,["Preg\u0103te\u0219te uleiul de morcov",2,B.b,"","C\u0103le\u0219te morcovul ras fin \xeen cele 30 ml ulei, apoi strecoar\u0103 uleiul colorat \xeen ciorb\u0103.",""],t.M)
B.ayR=new A.a(B.l,["Preg\u0103te\u0219te amestecul pentru dres",3,B.b,"","Amestec\u0103 cele 5 g\u0103lbenu\u0219uri cu cele 500 g sm\xe2nt\xe2n\u0103 \xeentr-un bol \xeenc\u0103p\u0103tor, p\xe2n\u0103 la omogenizare.",""],t.M)
B.ke=new A.a(B.l,["\xcenc\u0103lze\u0219te treptat amestecul",3,B.b,u.ao,"Ia oala de pe foc. Tempereaz\u0103 amestecul cu sup\u0103 fierbinte ad\u0103ugat\u0103 treptat, amestec\xe2nd continuu.",""],t.M)
B.kf=new A.a(B.l,["\xcencorporeaz\u0103 \u0219i g\u0103te\u0219te dresul",4,B.b,"","Toarn\u0103 amestecul temperat \xeen oal\u0103 \u0219i \xeenc\u0103lze\u0219te lent p\xe2n\u0103 la minimum 72\xb0C \xeen lichidul omogenizat, f\u0103r\u0103 clocot puternic.",""],t.M)
B.ax7=new A.a(B.l,["Potrive\u0219te usturoiul \u0219i o\u021betul",4,B.b,"","Adaug\u0103 usturoiul pisat \u0219i o\u021betul treptat, apoi potrive\u0219te sarea.",""],t.M)
B.dX=new A.a(B.l,["Serve\u0219te \u0219i p\u0103streaz\u0103 restul",5,B.b,""," Serve\u0219te cald. R\u0103ce\u0219te prompt restul \xeen recipiente mici \u0219i pune la frigider \xeen cel mult 2 ore. Re\xeenc\u0103lze\u0219te por\u021biile la minimum 74\xb0C.",""],t.M)
