B.axE=new A.a(B.l,["\xcenmoaie fasolea din ajun",-1,B.b,"","Alege \u0219i cl\u0103te\u0219te fasolea. Acoper\u0103 cu mult\u0103 ap\u0103 \u0219i \xeenmoaie 8\u201312 ore la frigider; arunc\u0103 apa.",""],t.M)
B.az8=new A.a(B.l,["Fierbe fasolea corect",-1,B.aq,"","Adu fasolea \xeen ap\u0103 proasp\u0103t\u0103 la fierbere viguroas\u0103 minimum 30 de minute, apoi continu\u0103 p\xe2n\u0103 e moale.",""],t.M)
B.ay2=new A.a(B.l,["Preg\u0103te\u0219te baza cu afum\u0103tur\u0103",-1,B.bC,"","Fierbe afum\u0103tura \xeen circa 3 l ap\u0103, conform etichetei, p\xe2n\u0103 este fraged\u0103 \u0219i g\u0103tit\u0103. \xcencepe verificarea orientativ dup\u0103 60 de minute. Verific\u0103 minimum 74\xb0C cu termometrul \xeen partea indicat\u0103, f\u0103r\u0103 atingerea osului sau a vasului.",""],t.M)
B.axR=new A.a(B.l,["Dezoseaz\u0103 \u0219i taie legumele",-1,B.b,"","Scoate carnea, strecoar\u0103 baza \u0219i dezoseaz\u0103. Taie ceapa, morcovii \u0219i ardeiul cubule\u021be.",""],t.M)
B.ax6=new A.a(B.l,["G\u0103te\u0219te legumele",-1,B.O,"","Fierbe legumele \u0219i cimbrul \xeen baza de carne aproximativ 20 de minute.",""],t.M)
B.axv=new A.a(B.l,["Adaug\u0103 fasolea \u0219i carnea",-1,B.b,"","Pune fasolea complet fiart\u0103, scurs\u0103, \u0219i carnea \xeen baza cu legume.",""],t.M)
B.az3=new A.a(B.l,["Pune ro\u0219iile \u0219i tarhonul",-1,B.x,"","Dizolv\u0103 pasta de ro\u0219ii \xeen pu\u021bin\u0103 zeam\u0103, adaug\u0103 \u0219i fierbe circa 10 minute. Pune tarhonul treptat.",""],t.M)
B.axT=new A.a(B.l,["Preg\u0103te\u0219te bolul de p\xe2ine op\u021bional",-1,B.b,"","Taie un capac din p\xe2ine \u0219i scoate miezul, l\u0103s\xe2nd pere\u021bi gro\u0219i. Umple numai la servire.",""],t.M)
B.axj=new A.a(B.l,["Serve\u0219te \u0219i p\u0103streaz\u0103 restul",5,B.b,"","Opre\u0219te focul \u0219i adaug\u0103 m\u0103rarul sp\u0103lat \u0219i tocat. Serve\u0219te cald. R\u0103ce\u0219te prompt restul \xeen recipiente mici \u0219i pune la frigider \xeen cel mult 2 ore. Re\xeenc\u0103lze\u0219te por\u021biile la minimum 74\xb0C.",""],t.M)
