B.axD=new A.a(B.l,["Preg\u0103te\u0219te legumele",-1,B.b,"","Taie ceapa, morcovul \u0219i ardeiul cubule\u021be de circa 5\u20138 mm. Cl\u0103te\u0219te \u0219i scurge orezul.",""],t.M)
B.ayF=new A.a(B.l,["Porne\u0219te puiul",0,B.b,"","Pune puiul \xeen 3 l ap\u0103 rece, adu aproape de fierbere \u0219i adun\u0103 spuma.",""],t.M)
B.ax4=new A.a(B.l,["G\u0103te\u0219te puiul cu legumele",1,B.av,"","Adaug\u0103 legumele \u0219i fierbe domol; verific\u0103 dup\u0103 aproximativ 45 de minute carnea fraged\u0103 \u0219i minimum 74\xb0C \xeen interior.",""],t.M)
B.azd=new A.a(B.l,["Dezoseaz\u0103 puiul",-1,B.b,"","Scoate puiul, \xeendep\u0103rteaz\u0103 pielea, oasele \u0219i cartilajele, apoi rupe carnea \xeen buc\u0103\u021bi mici.",""],t.M)
B.ax9=new A.a(B.l,["Fierbe orezul",2,B.u,"","Pune orezul scurs \xeen sup\u0103 \u0219i fierbe orientativ 15 minute; verific\u0103 bobul moale, apoi pune carnea \xeenapoi.",""],t.M)
B.A1=new A.a(B.l,["Preg\u0103te\u0219te amestecul pentru dres",3,B.b,"","Amestec\u0103 cele 3 g\u0103lbenu\u0219uri cu cele 300 g sm\xe2nt\xe2n\u0103 \xeentr-un bol \xeenc\u0103p\u0103tor, p\xe2n\u0103 la omogenizare.",""],t.M)
B.axA=new A.a(B.l,["Acre\u0219te cu l\u0103m\xe2ie",5,B.b,"","Cu focul oprit, adaug\u0103 treptat suc de l\u0103m\xe2ie, apoi sare, piper \u0219i m\u0103rar.",""],t.M)
