B.ayY=new A.a(B.l,["Separ\u0103 pe\u0219tele \u0219i preg\u0103te\u0219te legumele",-1,B.b,"","Separ\u0103 capetele f\u0103r\u0103 branhii \u0219i cozile de buc\u0103\u021bile de trunchi. Taie legumele cuburi de circa 1 cm.",""],t.M)
B.ax1=new A.a(B.l,["Fierbe baza",0,B.aj,"","Fierbe capetele, cozile \u0219i legumele \xeen 4 l ap\u0103 aproximativ 25 de minute, cu pu\u021bin\u0103 sare.",""],t.M)
B.ayO=new A.a(B.l,["Strecoar\u0103 foarte atent",-1,B.b,"","Scoate buc\u0103\u021bile mari \u0219i strecoar\u0103 supa fin. P\u0103streaz\u0103 numai lichidul \u0219i legumele recuperate f\u0103r\u0103 oase.",""],t.M)
