B.axP=new A.a(B.l,["F\u0103 g\u0103lu\u0219ca de prob\u0103",-1,B.b,"","Pune o por\u021bie mic\u0103 \xeen supa lini\u0219tit\u0103 \u0219i verific\u0103 dac\u0103 r\u0103m\xe2ne \xeentreag\u0103.",""],t.M)
B.ayD=new A.a(B.l,["Por\u021bioneaz\u0103 restul",2,B.b,"","Pune g\u0103lu\u0219te mici, cu spa\u021biu \xeentre ele, f\u0103r\u0103 s\u0103 le comprimi.",""],t.M)
B.azi=new A.a(B.l,["Fierbe bl\xe2nd \u0219i odihne\u0219te",3,B.x,"","Fierbe circa 10 minute la foc mic, \xeentorc\xe2nd delicat la jum\u0103tate; opre\u0219te \u0219i las\u0103 acoperit 10 minute.",""],t.M)
B.ayr=new A.a(B.l,["Verific\u0103 o g\u0103lu\u0219c\u0103 \xeen centru",3,B.b,"","Taie o g\u0103lu\u0219c\u0103 de prob\u0103: trebuie s\u0103 fie moale p\xe2n\u0103 \xeen centru, f\u0103r\u0103 gri\u0219 tare; urm\u0103re\u0219te minimum 72\xb0C \xeen centru.",""],t.M)
B.axo=new A.a(B.l,["Serve\u0219te \u0219i p\u0103streaz\u0103 restul",5,B.b,"","Pune \xeen boluri carne dezosat\u0103 \u0219i morcov fiert, adaug\u0103 supa cu g\u0103lu\u0219te \u0219i p\u0103trunjel sp\u0103lat \u0219i tocat. Serve\u0219te cald. R\u0103ce\u0219te prompt restul \xeen recipiente mici \u0219i pune la frigider \xeen cel mult 2 ore. Re\xeenc\u0103lze\u0219te por\u021biile la minimum 74\xb0C.",""],t.M)
