B.axB=new A.a(B.l,["Fierbe r\u0103d\u0103cinoasele",1,B.x,"","Pune ceapa, morcovul \u0219i ardeiul \xeen baza fierbinte \u0219i fierbe circa 10 minute.",""],t.M)
