B.ayG=new A.a(B.l,["Aromatizeaz\u0103 cu tarhon",3,B.b,"","Adaug\u0103 tarhonul tocat treptat \u0219i pu\u021bin din o\u021betul lui, dup\u0103 gust.",""],t.M)
