B.ayC=new A.a(B.l,["Taie legumele",-1,B.b,"","Taie ceapa \u0219i usturoiul fin, morcovii \u0219i apio cubule\u021be mici.",""],t.M)
B.az7=new A.a(B.l,["\xcenmoaie baza",1,B.b,"","G\u0103te\u0219te ceapa, morcovii \u0219i apio \xeen ulei p\xe2n\u0103 ceapa devine moale.",""],t.M)
B.ax8=new A.a(B.l,["Adaug\u0103 usturoiul \u0219i aromele",1,B.b,"","Pune usturoiul, oregano, busuiocul \u0219i piperul \u0219i amestec\u0103 scurt.",""],t.M)
