B.axW=new A.a(B.l,["Fierbe \u0219i verific\u0103 boabele",3,B.bC,"","Fierbe domol cel pu\u021bin 60 de minute \u0219i verific\u0103 lintea p\xe2n\u0103 devine moale.",""],t.M)
B.ayb=new A.a(B.l,["Regleaz\u0103 consisten\u021ba",4,B.b,"","Adaug\u0103 pu\u021bin\u0103 ap\u0103 fierbinte dac\u0103 supa este prea groas\u0103 \u0219i gust\u0103 \xeenainte de sare.",""],t.M)
B.awZ=new A.a(B.l,["Serve\u0219te \u0219i p\u0103streaz\u0103 restul",5,B.b,"","Por\u021bia mic\u0103 din surs\u0103 nu este automat o mas\u0103 complet\u0103; asocierile se aleg separat de cantit\u0103\u021bile acestei supe. Serve\u0219te cald. R\u0103ce\u0219te prompt restul \xeen recipiente mici \u0219i pune la frigider \xeen cel mult 2 ore. Re\xeenc\u0103lze\u0219te por\u021biile la minimum 74\xb0C.",""],t.M)
