B.apj=new A.a(B.c,["Monteaz\u0103 primul strat","Acoper\u0103 tava cu jum\u0103tate din pi\u0219coturile umezite \u0219i \xeentinde jum\u0103tate din crem\u0103, f\u0103r\u0103 s\u0103 strive\u0219ti baza.","Crema acoper\u0103 pi\u0219coturile uniform.","",3,B.b],t.M)
