B.amH=new A.a(B.c,["Preg\u0103te\u0219te ingredientele","Verific\u0103 pe\u0219tele cur\u0103\u021bat \u0219i \xeendep\u0103rteaz\u0103 branhiile r\u0103mase. P\u0103streaz\u0103 buc\u0103\u021bile mari de carne la rece. Cur\u0103\u021b\u0103 \u0219i taie ceapa, ardeii \u0219i morcovii \xeen buc\u0103\u021bi mari.","Tac\xe2murile \u0219i buc\u0103\u021bile de servire sunt separate.","",-1,B.b],t.M)
B.amZ=new A.a(B.c,["Fierbe baza de pe\u0219te","Pune capetele f\u0103r\u0103 branhii, cozile \u0219i legumele \xeen apa m\u0103surat\u0103. \xcenc\u0103lze\u0219te, spumeaz\u0103 \u0219i fierbe bl\xe2nd aproximativ 25 de minute, cu pu\u021bin\u0103 sare.","Legumele sunt moi \u0219i baza este aromat\u0103.","",0,B.aj],t.M)
B.aqo=new A.a(B.c,["Strecoar\u0103 foarte atent","Scoate buc\u0103\u021bile mari, apoi strecoar\u0103 supa prin sita deas\u0103 \xeen alt vas. Nu presa oasele prin sit\u0103. Pune zeama \xeenapoi pe foc.","Nu r\u0103m\xe2n fragmente de os \xeen lichid.","",0,B.b],t.M)
B.ang=new A.a(B.c,["Adaug\u0103 ro\u0219iile \u0219i acre\u0219te par\u021bial","Pune ro\u0219iile t\u0103iate sau pasate. Las\u0103-le s\u0103 se g\u0103teasc\u0103 \xeen baza fierbinte. Adaug\u0103 numai o parte din o\u021bet \u0219i p\u0103streaz\u0103 restul pentru potrivirea final\u0103.","Baza este fierbinte, iar ro\u0219iile s-au \xeenmuiat.","",1,B.b],t.M)
B.ap1=new A.a(B.c,["Pune buc\u0103\u021bile mari de pe\u0219te","Redu focul \u0219i a\u0219az\u0103 buc\u0103\u021bile \xeen zeam\u0103, \xeentr-un strat c\xe2t mai lejer. Nu amesteca cu lingura; mi\u0219c\u0103 u\u0219or oala doar dac\u0103 este necesar.","Buc\u0103\u021bile r\u0103m\xe2n \xeentregi \u0219i sunt acoperite de lichid.","",2,B.b],t.M)
B.tH=s([600,720],t.t)
B.anO=new A.a(B.c,["Verific\u0103 g\u0103tirea","Fierbe bl\xe2nd orientativ 10\u201312 minute, apoi verific\u0103 partea groas\u0103 a unei buc\u0103\u021bi: minimum 63\xb0C, f\u0103r\u0103 a atinge osul cu termometrul. Continu\u0103 dac\u0103 este necesar.","Carnea este opac\u0103, se desprinde \xeen fulgi \u0219i temperatura confirm\u0103 g\u0103tirea.","",2,B.tH],t.M)
B.apS=new A.a(B.c,["\xcencheie \u0219i serve\u0219te atent","Opre\u0219te focul, adaug\u0103 leu\u0219teanul tocat \u0219i potrive\u0219te sarea \u0219i o\u021betul gust\xe2nd zeama. Ridic\u0103 pe\u0219tele cu spumiera \u0219i avertizeaz\u0103 la servire c\u0103 pot exista oase fine.","Pe\u0219tele este complet g\u0103tit, iar zeama are acreala dorit\u0103.","",3,B.b],t.M)
