B.avU=new A.a(B.c,["Porne\u0219te baza de afum\u0103tur\u0103","Pune afum\u0103tura \xeen apa rece m\u0103surat\u0103. Adu la fierbere \u0219i adun\u0103 spuma. Fierbe bl\xe2nd conform etichetei, p\xe2n\u0103 carnea devine fraged\u0103; produsul gata fiert poate avea nevoie de mai pu\u021bin timp.","Carnea se desprinde u\u0219or de os sau se str\u0103punge u\u0219or.","",0,B.b],t.M)
B.amM=new A.a(B.c,["Taie legumele","Cur\u0103\u021b\u0103 ceapa, morcovul \u0219i ardeiul \u0219i toac\u0103-le cubule\u021be. Cur\u0103\u021b\u0103 cartofii \u0219i taie cuburi de aproximativ 2 cm. P\u0103streaz\u0103-i \xeen ap\u0103 rece curat\u0103 p\xe2n\u0103 \xeei pui \xeen sup\u0103.",u.M,"",-1,B.b],t.M)
B.avX=new A.a(B.c,["Scoate \u0219i dezoseaz\u0103 carnea","Ridic\u0103 afum\u0103tura cu spumiera. Dup\u0103 ce poate fi manevrat\u0103, \xeendep\u0103rteaz\u0103 oasele \u0219i taie carnea buc\u0103\u021bi. P\u0103streaz\u0103 zeama din oal\u0103.","Nu mai exist\u0103 fragmente de os \xeen carne.","",-1,B.b],t.M)
B.awm=new A.a(B.c,["Adaug\u0103 baza de legume","Pune ceapa, morcovul \u0219i ardeiul \xeen zeama fierbinte. Fierbe orientativ 10 minute, la foc mic spre mediu.","Morcovul \xeencepe s\u0103 se \xeenmoaie.","",1,B.x],t.M)
B.amw=new A.a(B.c,["G\u0103te\u0219te cartofii","Scurge cartofii \u0219i pune-i \xeen oal\u0103 \xeempreun\u0103 cu carnea. Fierbe bl\xe2nd p\xe2n\u0103 o furculi\u021b\u0103 intr\u0103 u\u0219or \xeen cuburi; dac\u0103 scade mult lichidul, completeaz\u0103 cu ap\u0103 fierbinte.","Cartofii sunt fragezi, dar \xee\u0219i p\u0103streaz\u0103 forma.","",2,B.b],t.M)
B.anJ=new A.a(B.c,["Pune tarhonul \u0219i gust\u0103","Adaug\u0103 tarhonul tocat \u0219i pu\u021bin din o\u021betul \xeen care a fost p\u0103strat. Amestec\u0103 \u0219i gust\u0103 o lingur\u0103 r\u0103corit\u0103 \xeenainte s\u0103 adaugi mai mult\u0103 sare sau acreal\u0103.","Aroma \u0219i sarea sunt potrivite pentru tine.","",3,B.b],t.M)
B.ar4=new A.a(B.c,["Tempereaz\u0103 sm\xe2nt\xe2na","Ia oala de pe foc. Amestec\u0103 sm\xe2nt\xe2na \xeen bol \u0219i adaug\u0103 c\xe2te pu\u021bin\u0103 zeam\u0103 fierbinte, omogeniz\xe2nd dup\u0103 fiecare adaos. Continu\u0103 p\xe2n\u0103 sm\xe2nt\xe2na este bine \xeenc\u0103lzit\u0103.","Amestecul din bol este omogen, f\u0103r\u0103 aglomer\u0103ri.","",4,B.b],t.M)
B.amb=new A.a(B.c,["\xcencorporeaz\u0103 \u0219i serve\u0219te","Toarn\u0103 sm\xe2nt\xe2na temperat\u0103 \xeen oal\u0103 \u0219i amestec\u0103. Dac\u0103 mai \xeenc\u0103lze\u0219ti pentru servire, folose\u0219te foc mic, f\u0103r\u0103 clocot puternic. Gust\u0103 din nou \xeenainte s\u0103 completezi condimentele.","Ciorba r\u0103m\xe2ne omogen\u0103, cu cartofi \xeentregi.","",5,B.b],t.M)
B.ZS=s([B.avU,B.amM,B.avX,B.awm,B.amw,B.anJ,B.ar4,B.amb],t.J)
B.aBt=new A.a(B.p,["Fierbere \u0219i dregere \xb7 Laura Lauren\u021biu","https://www.lauralaurentiu.ro/retete-culinare/supe-ciorbe/ciorba-de-cartofi-cu-afumatura-si-tarhon-ca-in-ardeal.html"],t.w)
