B.anu=new A.a(B.c,["Preg\u0103te\u0219te p\u0103st\u0103ile \u0219i legumele","Spal\u0103 p\u0103st\u0103ile proaspete, \xeendep\u0103rteaz\u0103 capetele \u0219i eventualele a\u021be \u0219i rupe-le \xeen buc\u0103\u021bi care \xeencap \xeen lingur\u0103. Taie ceapa, morcovul \u0219i ardeiul m\u0103runt. Pentru p\u0103st\u0103i congelate, urmeaz\u0103 eticheta.","P\u0103st\u0103ile nu au capete tari sau a\u021be.","",-1,B.b],t.M)
B.alR=new A.a(B.c,["\xcenmoaie baza de legume","\xcenc\u0103lze\u0219te uleiul pe foc mediu-mic. Pune ceapa, morcovul \u0219i ardeiul cu pu\u021bin\u0103 ap\u0103 \u0219i amestec\u0103 orientativ 5 minute.","Ceapa s-a \xeenmuiat, f\u0103r\u0103 s\u0103 fie ars\u0103.","",0,B.v],t.M)
B.auh=new A.a(B.c,["Fierbe fasolea verde","Toarn\u0103 apa fierbinte m\u0103surat\u0103 \u0219i pune p\u0103st\u0103ile. Fierbe bl\xe2nd orientativ 20 de minute, apoi verific\u0103 \u0219i continu\u0103 dac\u0103 sunt tari.","P\u0103st\u0103ile se rup \u0219i se mestec\u0103 u\u0219or, f\u0103r\u0103 textur\u0103 crud\u0103.","",1,B.O],t.M)
B.alL=new A.a(B.c,["Adaug\u0103 ro\u0219iile","Pune ro\u0219iile pasate sau t\u0103iate dup\u0103 \xeendep\u0103rtarea pieli\u021bei. Mai g\u0103te\u0219te orientativ 10 minute, amestec\xe2nd u\u0219or.","Ro\u0219iile sunt g\u0103tite \u0219i integrate \xeen zeam\u0103.","",2,B.x],t.M)
B.anh=new A.a(B.c,["Aromatizeaz\u0103 cu usturoi","Piseaz\u0103 usturoiul \u0219i adaug\u0103-l spre final. Las\u0103 un clocot u\u0219or, apoi opre\u0219te focul.","Usturoiul este distribuit uniform.","",3,B.b],t.M)
B.aw3=new A.a(B.c,["Drege numai dac\u0103 dore\u0219ti","Pentru varianta f\u0103r\u0103 sm\xe2nt\xe2n\u0103, treci la servire. Altfel, omogenizeaz\u0103 sm\xe2nt\xe2na \xeen bol, \xeenc\u0103lze\u0219te-o treptat cu zeam\u0103 fierbinte, apoi toarn\u0103 amestecul \xeen oal\u0103, amestec\xe2nd.","Sm\xe2nt\xe2na se \xeencorporeaz\u0103 f\u0103r\u0103 aglomer\u0103ri.","",4,B.b],t.M)
B.alt=new A.a(B.c,["\xcencheie cu m\u0103rar","Pune m\u0103rarul sp\u0103lat \u0219i tocat. Gust\u0103 o lingur\u0103 r\u0103corit\u0103 \u0219i ajusteaz\u0103 sarea. Serve\u0219te; varianta cu sm\xe2nt\xe2n\u0103 este cea ilustrat\u0103.","P\u0103st\u0103ile sunt complet g\u0103tite, iar gustul este potrivit.","",5,B.b],t.M)
B.a0K=s([B.anu,B.alR,B.auh,B.alL,B.anh,B.aw3,B.alt],t.J)
